def is_2x2_full_of_2s(grid, r, c):
    h, w = len(grid), len(grid[0])
    if r+1 >= h or c+1 >= w:
        return False
    return all(grid[r+i][c+j] == 2 for i in range(2) for j in range(2))

def find_2x2_blocks(grid):
    blocks = []
    h, w = len(grid), len(grid[0])
    for r in range(h-1):
        for c in range(w-1):
            if is_2x2_full_of_2s(grid, r, c):
                blocks.append((r, c))
    return blocks

blocks = find_2x2_blocks(demo_input)

def blocks_adjacent(b1, b2):
    r1, c1 = b1
    r2, c2 = b2
    return (abs(r1-r2) <= 1 and abs(c1-c2) <= 1)

# Build adjacency graph
adjacency = []
seen_adj = set()
for i, b1 in enumerate(blocks):
    for j, b2 in enumerate(blocks):
        if i < j and blocks_adjacent(b1, b2):
            key = (tuple(sorted([b1, b2])))
            if key not in seen_adj:
                seen_adj.add(key)
                adjacency.append((b1, b2))

