    print(f"  {b1} adjacent to {b2}")

# Connected components of blocks
def find_connected_components(blocks):
    visited = set()
    components = []

    def dfs(block, component):
        visited.add(block)
        component.append(block)
        for adj_block in adjacency:
            if adj_block[0] == block:
                dfs(adj_block[1], component)
            if adj_block[1] == block:
                dfs(adj_block[0], component)

    for block in blocks:
        if block not in visited:
            component = []
            dfs(block, component)
            if component:
                components.append(component)

    return components

components = find_connected_components(blocks)
print(f"\nConnected components of blocks: {len(components)}")
for i, comp in enumerate(components):
    print(f"  Component {i}: {comp}")

# For each block, check if its component has size > 1
print("\nBlock fates based on component size:")
for r, c in blocks:
    # Find component
